"""Every round-2 number quoted in the manuscript, generated from the result tables (do not edit the output by hand).

    .venv/bin/python round2_numbers.py      # -> results/review_r2/ROUND2_NUMBERS.md
"""
import os

import numpy as np
import pandas as pd

HERE = os.path.dirname(os.path.abspath(__file__))
R = os.path.join(HERE, "results")
out = ["# Round-2 numbers (generated by `round2_numbers.py`; do not edit)", ""]


def rng_(v, f="{:.2f}"):
    v = pd.Series(v).dropna()
    return (f + "–" + f).format(v.min(), v.max()) if len(v) else "–"


# S
S = pd.read_csv(os.path.join(R, "serial_retention", "sr_summary.csv")).set_index("key")
out += ["## S, serial allele retention (registered)", "", "| genotype | kind | unmutated alive g1/g8 | retained g1 | lost/erased/retained g8 | sites g1/g8 (never executed g8) |", "|---|---|---|---|---|---|"]
for k, r in S.iterrows():
    out.append(f"| {k} | {r.kind} | {r.ctrl_alive_g1:.2f}/{r.ctrl_alive_g8:.2f} | {r.retained_g1:.2f} | {r.lost_g8:.2f}/{r.erased_g8:.2f}/{r.retained_g8:.2f} | {r.sites_g1}/{r.sites_g8} ({r.sites_unexec_g8}) |")
push = S.loc[["pusher16", "pusher50", "pusher64", "pusher32_8080"]]
reg = S.loc[["ret16", "ldir20", "ldir32"]]
tra = S.loc[["lethal16_s4009", "genome16_s6006", "genome20_s6003", "genome20_s6004", "closer32_8080_p1", "closer32_8080_p2"]]
out += ["", f"- pushers: unmutated lineages lost by g8 {rng_(1 - push.ctrl_alive_g8)}; alive at g4 {rng_(push.ctrl_alive_g4)}; retained g1 {rng_(push.retained_g1)}, g4 {rng_(push.retained_g4)}; first-generation sites {rng_(push.sites_g1, '{:.0f}')}, at g8 {rng_(push.sites_g8, '{:.0f}')}",
        f"- regenerators (ret16, ldir20, ldir32): unmutated alive g8 {rng_(reg.ctrl_alive_g8)}; erased g8 {rng_(reg.erased_g8)}; retained g8 {rng_(reg.retained_g8)}; lost g8 {rng_(reg.lost_g8)}; sites g8 {rng_(reg.sites_g8, '{:.0f}')}",
        f"- transmitters (lethal, three genomes, constructed x2): unmutated alive g8 {rng_(tra.ctrl_alive_g8)}; retained g8 {rng_(tra.retained_g8)}; sites g8 {rng_(tra.sites_g8, '{:.0f}')}; never executed at g8 {rng_(tra.sites_unexec_g8, '{:.0f}')}",
        f"- L = 50 closer (jr50): unmutated alive g1 {S.loc['jr50', 'ctrl_alive_g1']:.2f}, g2 {S.loc['jr50', 'ctrl_alive_g2']:.2f}, g4 {S.loc['jr50', 'ctrl_alive_g4']:.2f}; retained g1 {S.loc['jr50', 'retained_g1']:.2f}, g4 {S.loc['jr50', 'retained_g4']:.2f}", ""]
K = pd.read_csv(os.path.join(R, "serial_retention", "kin_summary.csv"))
out += ["## Kin partners (post hoc)", ""] + [f"- {r.genotype} vs {r.partners_from}: retained g1 {r.retained_g1:.2f}, g2 {r.retained_g2:.2f}, g4 {r.retained_g4:.2f}, g8 {r.retained_g8:.2f}" for r in K.itertuples()] + [""]

# V
V = pd.read_csv(os.path.join(R, "marker_check", "marker_check.csv"))
v300 = V[V.step.isin([300, 500, 1000])]
out += ["## V, marker vs confinement (registered)", "",
        f"- marker share at steps 300–1,000 {rng_(v300.marker_share_soup)}; confined share {rng_(v300.confined_share)}; P(confined | marker) {rng_(V[V.step > 0].confined_given_marker)}; P(confined | no marker) {rng_(V[V.step > 0].confined_given_no_marker)}",
        f"- marker share at step 200: {rng_(V[V.step == 200].marker_share_soup)}; at 300: {rng_(V[V.step == 300].marker_share_soup)}", ""]

# Q
Q = pd.read_csv(os.path.join(R, "population", "population_worlds.csv"))
out += ["## Q, population sample of final snapshots (registered)", "", "| stage | L | worlds | modal tape confined | majority of heritable cells confined | confined among heritable (median, range) | heritable (median) | modal share (median, range) |", "|---|---|---|---|---|---|---|---|"]
for (st, L), d in Q.groupby(["stage", "L"]):
    out.append(f"| {st} | {L} | {len(d)} | {int(d.modal_confined.sum())} | {int((d.confined_given_heritable > 0.5).sum())} | {d.confined_given_heritable.median():.2f} ({rng_(d.confined_given_heritable)}) | {d.frac_heritable.median():.2f} | {d.modal_share.median():.3f} ({rng_(d.modal_share, '{:.3f}')}) |")
out.append("")

# Q2
p2 = os.path.join(R, "population", "classes_snapshots.csv")
if os.path.exists(p2):
    C = pd.read_csv(p2)
    F = C[C.snapshot == "final"]
    out += ["## Q2, population classes (exploratory, R2b)", "", "Final snapshot; shares are of heritable cells.", "",
            "| stage | L | worlds | heritable (median) | open (median) | regenerator (median) | transmitter (median) | majority open / regen / transmitter | transmitter max over worlds | never-executed sites of transmitters (median) |", "|---|---|---|---|---|---|---|---|---|---|"]
    for (st, L), d in F.groupby(["stage", "L"]):
        maj = [int((d[f"frac_{c}_of_heritable"] > 0.5).sum()) for c in ("open", "regenerator", "transmitter")]
        out.append(f"| {st} | {L} | {len(d)} | {d.frac_heritable.median():.2f} | {d.frac_open_of_heritable.median():.2f} | {d.frac_regenerator_of_heritable.median():.2f} | {d.frac_transmitter_of_heritable.median():.2f} | "
                   f"{maj[0]} / {maj[1]} / {maj[2]} | {d.frac_transmitter_of_heritable.max():.2f} | {d.median_unexec_sites_transmitters.median():.1f} |")
    out += ["", "Over time (snapshots with heritable share >= 0.2): worlds where transmitters ever held >= 10% / > 50% of heritable cells, and the largest share", ""]
    T = C[C.frac_heritable >= 0.2]
    for (st, L), d in T.groupby(["stage", "L"]):
        mx = d.groupby("seed").frac_transmitter_of_heritable.max()
        out.append(f"- {st} L = {L}: >= 10% in {int((mx >= 0.1).sum())} of {len(mx)}, > 50% in {int((mx > 0.5).sum())}; largest {mx.max():.2f}")
    out.append("")
    # closure per world at population level: majority of heritable cells confined at the final snapshot
    out += ["Population closure at the final snapshot (confined share of heritable cells > 0.5): " + "; ".join(
        f"{st} L{L} {int((d.frac_confined_of_heritable > 0.5).sum())}/{len(d)}" for (st, L), d in F.groupby(["stage", "L"])), ""]

# A1/A2
for tag in ("A1", "A2"):
    rp = os.path.join(R, "invasion_closer", f"{tag}_classes.csv")
    if not os.path.exists(rp):
        continue
    C = pd.read_csv(rp)
    C["cond"] = C.file.str.replace(r"_s\d+_final\.npy", "", regex=True)
    out += [f"## {tag} final populations (classes of 64 random cells per soup)", ""]
    for cond, d in C.groupby("cond"):
        out.append(f"- {cond}: soups {len(d)}; heritable {rng_(d.frac_heritable)}; open {rng_(d.frac_open_of_heritable)}; regenerator {rng_(d.frac_regenerator_of_heritable)}; transmitter {rng_(d.frac_transmitter_of_heritable)}; most common tape share {rng_(d.top1_share, '{:.3f}')}; most common tape: {d.top1.iloc[0][:23]}…")
    D = pd.read_csv(os.path.join(R, "invasion_closer", f"{tag}.csv"))
    other = "pusher" if tag == "A1" else "ldir"
    inv = D[(D.resident == other) & (D.invader == "closer")]
    t50 = inv[inv.loop_share_posthoc > 0.5].groupby("seed").step.min()
    gone = inv[inv[f"{other}_class_share"] < 0.01].groupby("seed").step.min()
    out += [f"- closer into {other}: loop body > 50% first at steps {', '.join(str(int(x)) for x in t50.values) or 'never'}; {other} class < 1% first at {', '.join(str(int(x)) for x in gone.values) or 'never'}", ""]
pc = os.path.join(R, "serial_retention", "posthoc_cells.csv")
if os.path.exists(pc):
    P = pd.read_csv(pc)
    t = P[P.sites_g8 >= 10]
    out += ["## Random transmitter cells of the invasion soups (post hoc)", "", f"- {len(t)} of {len(P)} cells with >= 10 sites at g8: never-executed sites {rng_(t.sites_unexec_g8, '{:.0f}')}, retained g8 {rng_(t.retained_g8)}, unmutated alive g8 {rng_(t.ctrl_alive_g8)}", ""]
open(os.path.join(R, "review_r2", "ROUND2_NUMBERS.md"), "w").write("\n".join(out) + "\n")
print("\n".join(out))
